        // Important level transition points.
        setSpecialLocation(STAIRS_DOWN_X, STAIRS_DOWN_Y, LocationType.STAIRS_DOWN); // to level 3
        setSpecialLocation(STAIRS_UP_X, STAIRS_UP_Y, LocationType.STAIRS_UP);       // from level 1
        
        
